// ===== Node: Guardrails: validate AI output =====
// Any failure returns source:"fallback" and the browser shows its deterministic, rules-based summary.
const ctx = $('Validate input & build prompt').first().json;
const res = $input.first().json;
const fail = reason => [{ json: { source: 'fallback', summary: null, reason } }];
if (!ctx.valid) return fail('invalid_input: ' + ctx.error);
if (res.error || !res.candidates) return fail('llm_error');
let out;
try { out = JSON.parse(res.candidates[0].content.parts.filter(p => !p.thought).map(p => p.text || '').join('')); }
catch (e) { return fail('not_json'); }
const s = String(out.summary || '').replace(/\s+/g, ' ').trim();
const words = s.split(' ').length;
if (words < 40 || words > 150) return fail('length_' + words);
if (/\d|€|%|\$|ευρώ|euro/i.test(s)) return fail('contains_numbers_or_money');
if (/[*#_`>]|^\s*-/.test(s)) return fail('markdown');
for (const name of ctx.forbidden) if (s.toLowerCase().includes(name.toLowerCase())) return fail('mentions_unrecommended_' + name);
if (/go for eat|edenred|pluxee|sodexo|ticket restaurant|natural greece|benefit plus/i.test(s)) return fail('mentions_other_brand');
if (!ctx.allowed.some(n => s.includes(n))) return fail('no_recommended_product');
const greek = (s.match(/[Ͱ-Ͽἀ-῿]/g) || []).length, latin = (s.match(/[a-z]/gi) || []).length;
if (ctx.lang === 'el' && greek < latin) return fail('wrong_language');
if (ctx.lang === 'en' && greek > 0) return fail('wrong_language');
return [{ json: { source: 'ai', summary: s, model: ctx.model } }];
